out=ROOT/'out/v137';data=(out/'multianchor.raw.bin').read_bytes();a=np.frombuffer(data[432:],dtype='<i2').reshape(-1,3,3).astype(np.int32);t=a.copy();t[:,1:,:]-=a[:,:-1,:];t[:,:,1:]-=a[:,:,:-1];t[:,1:,1:]+=a[:,:-1,:-1];assert t.min()>=-32768 and t.max()<=32767;decoded=t.astype('<i2').tobytes();start=time.process_time();stream=lzma.compress(decoded,format=lzma.FORMAT_XZ,check=lzma.CHECK_CRC32,preset=6);assert lzma.decompress(stream)==decoded;inverse=np.cumsum(np.cumsum(t,axis=1),axis=2);assert np.array_equal(inverse,a);meta=json.loads((ROOT/'reports/V137-multianchor-compression.json').read_text());asset=out/'joint-multianchor-difference.bin';asset.write_bytes(b'TRMXZ002'+data[8:432]+bytes.fromhex(meta['baseline_recipe'])+stream);r={'state':'compressed candidate; full validation pending','lossless':True,'architecture_only':True,'fit_labels_used':False,'holdout_used':False,'inverse_exact':True,'asset_bytes':asset.stat().st_size,'decoded_bytes':len(decoded),'decoded_transform_sha256':hashlib.sha256(decoded).hexdigest(),'reconstructed_sha256':hashlib.sha256(inverse.astype('<i2').tobytes()).hexdigest(),'original_raw_sha256':hashlib.sha256(data[432:]).hexdigest(),'compression_cpu_seconds':time.process_time()-start,'estimated_profile_bytes_before_executable_growth':99295621-42083456+38859068-3861388+asset.stat().st_size};(ROOT/'reports/V137-multianchor-difference-compression.json').write_text(json.dumps(r,indent=2)+'\n');print(json.dumps(r,indent=2))
